-- Bounded loadout changes for the single isolated test actor. Original gear is
-- retained in the real bag; only items generated by this instance are removed.
local M={}
local choices={heavy='52306-rebirth.mod',katana='476-gamedata.base',sabre='52304-rebirth.mod',
 polearm='52301-rebirth.mod',blunt='52297-rebirth.mod',hacker='52299-rebirth.mod',chainsword='100-JACK_ChainswordLab.mod'}
function M.new(api)
 local lease,worldTag,gaitFixture
 local C={}
 local function same(a,b)return api.same and api.same(a,b) or a==b end
 local function contains(inv,item)
  if same(inv:getPrimaryWeapon(),item) or same(inv:getSecondaryWeapon(),item) then return true end
  local all=inv:getAllItems();for i=1,#all do if same(all[i],item) then return true end end
  return false
 end
 local function meta(item)
  if not item then return {} end
  local w=item:isWeapon()
  local result={id=item.data and item.data.stringID or '',name=item.data and item.data.name or '',
   quality=item.quality,equipped=item.isEquipped,section=item.inventorySection or '',weight=item:getItemWeight(),width=item.itemWidth,height=item.itemHeight,
   category=w and tonumber(w:getCategory()) or -1,
   animation_category=w and tonumber(w:getCategory_animationOverride()) or -1}
  if api.gunState then result.gun=api.gunState(item)end
  return result
 end
 function C.reset()lease=nil;worldTag=nil;gaitFixture=nil end
 function C.select(c,choice)
  api.guard(c);assert(choice=='lamp-status' or choice=='lamp-off' or choice=='lamp-on' or choice=='lamp-fast' or choice=='lamp-normal' or choice=='status' or choice=='draw' or choice=='draw-primary' or choice=='draw-secondary' or choice=='secondary' or choice=='bag' or choice=='stash-primary' or choice=='inventory-show' or choice=='original' or choice=='reset-health' or choice=='gait-fixture' or choice=='gait-restore' or choices[choice],'Unknown test weapon choice')
  local world=api.world();if worldTag and worldTag~=world then C.reset() end;worldTag=world
  local inv=assert(c:getInventory());local owner=c:getHandle():toString()
  if choice=='lamp-status' then
   local result=assert(_G.JACK_T60_LAMP_PROBE,'Lamp runtime unavailable')(c)
   result.game_hours=world:getTimeStamp_inGameHours():getTotalHours()
   return result
  end
  if choice=='status' then
   local items={};local all=inv:getAllItems();for i=1,#all do local x=all[i];if x:isWeapon() then items[#items+1]=meta(x) end end
   local sections={}
   if inv.getAllSections then local all=inv:getAllSections();for i=1,#all do local sec=all[i];sections[sec.name]={width=sec.width,height=sec.height,equipped=sec.isAnEquippedItemSection,limited_slot=tonumber(sec.limitedSlot)}end end
   return {primary=meta(inv:getPrimaryWeapon()),secondary=meta(inv:getSecondaryWeapon()),current=meta(c:getCurrentWeapon()),leased=lease~=nil,weapons=items,sections=sections}
  end
  if api.active and choice~='original' and choice~='reset-health' then api.active(c) end
  assert(api.paused(),'Pause the isolated test before changing loadout')
  assert(not api.autosave(),'Disable autosave for temporary test loadouts')
  if choice=='lamp-off' or choice=='lamp-on' then
   assert(_G.JACK_T60_LAMP_ENABLE,'Lamp runtime unavailable')(choice=='lamp-on');return {lamp_enabled=choice=='lamp-on'}
  end
  if choice=='lamp-fast' or choice=='lamp-normal' then
   world:setGameSpeed(choice=='lamp-fast' and 3 or 1,false);return {speed=choice=='lamp-fast' and 3 or 1}
  end
  if choice=='gait-fixture' then
   assert(not gaitFixture,'Restore the existing gait fixture first')
   local stats=c:getStats();gaitFixture={owner=owner,strength=stats._strength};stats._strength=150
   return {fixture_only=true,original_strength=gaitFixture.strength,temporary_strength=stats._strength}
  end
  if choice=='gait-restore' or choice=='original' then
   if gaitFixture then assert(gaitFixture.owner==owner);c:getStats()._strength=gaitFixture.strength;gaitFixture=nil end
   if choice=='gait-restore' then return {restored=true}end
  end
  if choice=='reset-health' then
   c:healCompletely();return {fixture_health_reset=true}
  end
  if choice=='inventory-show' then
   local ui=inv:getInventoryGUI()or getForgottenGUI():showInventory(c:getHandle(),true,0,0)
   assert(ui,'Inventory GUI unavailable');ui:show(true);return {shown=true}
  end
  if choice=='draw' or choice=='draw-primary' or choice=='draw-secondary' then
   local item=assert(choice=='draw-secondary' and inv:getSecondaryWeapon() or choice=='draw-primary' and inv:getPrimaryWeapon() or lease and lease.generated or inv:getPrimaryWeapon(),'No test weapon to draw')
   if choice=='draw-secondary' then assert(item.data.stringID=='100-JACK_ChainswordLab.mod','Secondary drawing limited to chainsword')end
   assert(c:drawWeapon(item,item.inventorySection),'Engine refused to draw primary weapon')
   return {drawn=true,primary=meta(item)}
  end
  if choice=='secondary' or choice=='bag' or choice=='stash-primary' then
   assert(lease and lease.owner==owner and same(lease.inventory,inv),'An active isolated weapon lease is required')
   local generated=assert(lease.generated,'No generated chainsword');assert(generated.data.stringID=='100-JACK_ChainswordLab.mod','Secondary tools limited to generated chainsword')
   if api.sheathe then api.sheathe(c)end
   local item=choice=='stash-primary' and lease.original or generated
   local dest=assert(inv:getSection(choice=='secondary' and 'hip' or 'main'),'Target section missing')
   local source=assert(inv:getSection(item.inventorySection),'Source section missing')
   if not same(source,dest) then
    assert(dest:hasRoomForItem(item.data,1),'Target section has no room')
    if choice=='secondary' then assert(dest:canItemGoHere(item,0,0),'Engine rejects this item in the target section')end
    assert(source:removeItem(item),'Could not release source section')
    if not dest:addItem(item,1) then assert(source:addItem(item,1),'Transfer rollback failed');error('Target section refused item')end
   end
   if choice=='secondary' and not lease.original.isEquipped then assert(inv:equipItem(lease.original),'Could not restore original primary weapon')end
   inv:notifyModified()
   if choice=='secondary' then assert(same(inv:getSecondaryWeapon(),generated),'Secondary weapon readback mismatch')end
   return {transferred=true,primary=meta(inv:getPrimaryWeapon()),secondary=meta(inv:getSecondaryWeapon()),generated=meta(generated),target={name=dest.name,width=dest.width,height=dest.height}}
  end
  if api.sheathe then api.sheathe(c) end
  if lease then assert(lease.owner==owner and same(lease.inventory,inv),'Loadout owner changed') end
  if choice=='original' and not lease then return {restored=true,primary=meta(inv:getPrimaryWeapon())} end
  if not lease then
   local original=assert(inv:getPrimaryWeapon(),'An original primary weapon is required')
   assert(original.isEquipped,'Original weapon is not equipped')
   local manufacturer=api.manufacturer and api.manufacturer() or original.manufacturerData
   assert(manufacturer,'Test melee manufacturer unavailable')
   local bag=assert(inv:getSection('main'))
   lease={owner=owner,inventory=inv,original=original,manufacturer=manufacturer,count=0}
   if not bag:hasRoomForItem(original.data,1) then
    assert(bag.width>0 and bag.height>0 and bag.width<=20 and bag.height<=20,'Unexpected test inventory dimensions')
    lease.bag=bag;lease.width=bag.width;lease.height=bag.height
    inv:resizeSection(bag,20,20,false)
    assert(bag:hasRoomForItem(original.data,1),'No room after bounded test inventory enlargement')
   end
  end
  local current=lease
  if current.generated then
   -- Never remove an item merely because its data ID matches a test weapon.
   local item=current.generated
   assert(contains(inv,item),'Generated weapon left the isolated test inventory')
   assert(inv:removeItemAutoDestroy(item,1),'Could not remove this session generated weapon')
   current.generated=nil
  end
  if choice=='original' then
   if not current.original.isEquipped then assert(inv:equipItem(current.original),'Could not restore original primary weapon')end
   assert(same(inv:getPrimaryWeapon(),current.original),'Original primary readback mismatch')
   if current.bag then inv:resizeSection(current.bag,current.width,current.height,false) end
   inv:notifyModified();lease=nil
   return {restored=true,primary=meta(inv:getPrimaryWeapon())}
  end
  assert(current.count<8,'Temporary weapon generation limit reached')
  local data=assert(api.lookup(choices[choice]),'Test weapon data unavailable')
  local original=current.original;local bag=assert(inv:getSection('main'))
  if original.isEquipped then
   local source=assert(inv:getSection(original.inventorySection))
   assert(source:removeItem(original),'Could not release original weapon slot')
   if not bag:addItem(original,1) then
    assert(source:addItem(original,1),'Original slot rollback failed');error('Could not retain original weapon')
   end
  end
  if not bag:hasRoomForItem(data,1) then
   if not current.bag then current.bag=bag;current.width=bag.width;current.height=bag.height end
   inv:resizeSection(bag,20,20,false)
   assert(bag:hasRoomForItem(data,1),'No room after bounded fixture enlargement')
  end
  local generated=assert(c:generateWeapon(data,current.manufacturer),'Engine weapon factory failed')
  current.generated=generated;current.count=current.count+1
  if not contains(inv,generated) then assert(inv:addItem(generated,1,false,false),'Could not add generated weapon') end
  assert(contains(inv,generated),'Factory placed the weapon outside the isolated test')
  if not generated.isEquipped then assert(inv:equipItem(generated),'Could not equip generated weapon') end
  inv:notifyModified()
  assert(same(inv:getPrimaryWeapon(),generated) or same(inv:getSecondaryWeapon(),generated),
   'Generated weapon is not in either weapon slot: '..tostring(generated.inventorySection))
  return {choice=choice,generated_count=current.count,primary=meta(generated),original=meta(original)}
 end
 return C
end
return M
